namespace BuildingIconGenerator.Api
{
    using System;
    using System.Collections.Concurrent;
    using System.Collections.Generic;
    using System.IO;
    using BuildingIconGenerator.Storage;
    using Game.Prefabs;

    /// <summary>
    /// Public access to the building icons generated by Building Icon Generator, for other mods and
    /// for the game's UI.
    ///
    /// <para>Every lookup is a hash-map read - no folder scan, no file access - and is safe from any
    /// thread. Icons are 1024x1024 RGBA PNGs with a transparent background, stored in
    /// <c>ModsData/BuildingIconGenerator/icons</c> and also served to the game's UI (Coherent) as
    /// <c>coui://buildingicons/&lt;file&gt;</c>. Each icon also has a 128x128 thumbnail for the UI,
    /// the size the game uses for its own thumbnails (see <see cref="TryGetThumbnailUri(string, out string)"/>).</para>
    ///
    /// <para>Buildings are identified by prefab name (<see cref="PrefabBase"/>.name). Overloads taking
    /// the prefab itself are provided for convenience.</para>
    ///
    /// <para>From another mod without a compile-time reference, the same members can be reached
    /// through reflection:
    /// <c>Type.GetType("BuildingIconGenerator.Api.BuildingIcons, BuildingIconGenerator")</c>.</para>
    /// </summary>
    public static class BuildingIcons
    {
        /// <summary>Host under which the icons folder is mapped for the game's UI.</summary>
        public const string UriHost = "buildingicons";

        /// <summary>
        /// Version of this API. Raised whenever a member changes meaning. A property rather than a
        /// constant, so a mod compiled against an older BIG reads the version actually installed.
        /// </summary>
        public static int ApiVersion => 1;

        private static readonly ConcurrentQueue<string> s_Requests = new ConcurrentQueue<string>();

        /// <summary>
        /// Raised on the main thread after a building's icon has been written or rewritten.
        /// The argument is the prefab name.
        /// </summary>
        public static event Action<string> IconUpdated;

        /// <summary>True once the registry has been loaded (right after the mod loads).</summary>
        public static bool IsAvailable => IconRegistry.Shared != null;

        /// <summary>True when the icons are reachable from the UI through <c>coui://buildingicons/</c>.</summary>
        public static bool UriAvailable { get; private set; }

        /// <summary>True while icons are being generated.</summary>
        public static bool IsGenerating { get; internal set; }

        /// <summary>Folder holding the icons, or null before the registry is loaded.</summary>
        public static string Folder => IconRegistry.Shared?.Folder;

        /// <summary>Number of buildings that have an icon.</summary>
        public static int Count => IconRegistry.Shared?.Count ?? 0;

        /// <summary>Full path of a building's PNG.</summary>
        public static bool TryGetPath(string prefabName, out string path)
        {
            path = IconRegistry.Shared?.PathOf(prefabName);
            return path != null;
        }

        /// <summary>Full path of a building's PNG.</summary>
        public static bool TryGetPath(PrefabBase prefab, out string path)
        {
            path = null;
            return prefab != null && TryGetPath(prefab.name, out path);
        }

        /// <summary>
        /// UI address of a building's icon, usable as an image source in the game's UI or as
        /// <c>UIObject.m_Icon</c>, e.g. <c>coui://buildingicons/EU_ResidentialLow01_L1_3x6.png?v=…</c>.
        /// The <c>v</c> parameter changes whenever the icon is rewritten, so a UI never keeps showing
        /// an outdated copy.
        /// The address resolves once <see cref="UriAvailable"/> is true (when the game has loaded).
        /// </summary>
        public static bool TryGetUri(string prefabName, out string uri)
        {
            uri = null;

            if (IconRegistry.Shared == null || !IconRegistry.Shared.TryGet(prefabName, out var entry))
            {
                return false;
            }

            // The write time makes every version of an icon a different address, so the UI shows a
            // regenerated icon instead of the copy it already cached. The UI ignores the query
            // when it reads the file.
            uri = entry.WrittenTicks > 0
                ? $"coui://{UriHost}/{Uri.EscapeDataString(entry.File)}?v={entry.WrittenTicks}"
                : $"coui://{UriHost}/{Uri.EscapeDataString(entry.File)}";
            return true;
        }

        /// <summary>UI address of a building's icon.</summary>
        public static bool TryGetUri(PrefabBase prefab, out string uri)
        {
            uri = null;
            return prefab != null && TryGetUri(prefab.name, out uri);
        }

        /// <summary>
        /// UI address of a building's 128x128 thumbnail, e.g.
        /// <c>coui://buildingicons/thumbnails/EU_ResidentialLow01_L1_3x6.png?v=…</c>. Prefer it for
        /// anything shown at button size (such as <c>UIObject.m_Icon</c>): the UI draws images
        /// without mipmaps, so the full-size icon shrunk that much looks jagged and shimmers.
        /// </summary>
        public static bool TryGetThumbnailUri(string prefabName, out string uri)
        {
            uri = null;

            if (IconRegistry.Shared == null || !IconRegistry.Shared.TryGet(prefabName, out var entry))
            {
                return false;
            }

            string address = $"coui://{UriHost}/{IconRegistry.ThumbnailFolderName}/{Uri.EscapeDataString(entry.File)}";
            uri = entry.WrittenTicks > 0 ? $"{address}?v={entry.WrittenTicks}" : address;
            return true;
        }

        /// <summary>UI address of a building's 128x128 thumbnail.</summary>
        public static bool TryGetThumbnailUri(PrefabBase prefab, out string uri)
        {
            uri = null;
            return prefab != null && TryGetThumbnailUri(prefab.name, out uri);
        }

        /// <summary>Full path of a building's 128x128 thumbnail PNG.</summary>
        public static bool TryGetThumbnailPath(string prefabName, out string path)
        {
            path = IconRegistry.Shared?.ThumbnailPathOf(prefabName);
            return path != null;
        }

        /// <summary>Full path of a building's 128x128 thumbnail PNG.</summary>
        public static bool TryGetThumbnailPath(PrefabBase prefab, out string path)
        {
            path = null;
            return prefab != null && TryGetThumbnailPath(prefab.name, out path);
        }

        /// <summary>True when the building has an icon on disk.</summary>
        public static bool HasIcon(string prefabName)
        {
            return IconRegistry.Shared != null && IconRegistry.Shared.TryGet(prefabName, out _);
        }

        /// <summary>True when the building has an icon on disk.</summary>
        public static bool HasIcon(PrefabBase prefab)
        {
            return prefab != null && HasIcon(prefab.name);
        }

        /// <summary>When the building's icon was last written (UTC).</summary>
        public static bool TryGetWriteTime(string prefabName, out DateTime utc)
        {
            utc = DateTime.MinValue;

            if (IconRegistry.Shared == null || !IconRegistry.Shared.TryGet(prefabName, out var entry) || entry.WrittenTicks <= 0)
            {
                return false;
            }

            utc = new DateTime(entry.WrittenTicks, DateTimeKind.Utc);
            return true;
        }

        /// <summary>Snapshot of the prefab names of every building that has an icon.</summary>
        public static IReadOnlyList<string> GetAll()
        {
            return IconRegistry.Shared?.Names() ?? new List<string>();
        }

        /// <summary>
        /// Asks for a building's icon to be generated (or regenerated) at the next opportunity, which
        /// is the main menu when automatic generation is enabled. <see cref="IconUpdated"/> fires once
        /// it has been written.
        /// </summary>
        public static void RequestGeneration(string prefabName)
        {
            if (!string.IsNullOrEmpty(prefabName))
            {
                s_Requests.Enqueue(prefabName);
            }
        }

        /// <summary>Asks for a building's icon to be generated (or regenerated) at the next opportunity.</summary>
        public static void RequestGeneration(PrefabBase prefab)
        {
            if (prefab != null)
            {
                RequestGeneration(prefab.name);
            }
        }

        internal static bool TryTakeRequest(out string prefabName)
        {
            return s_Requests.TryDequeue(out prefabName);
        }

        internal static void RaiseUpdated(string prefabName)
        {
            var handlers = IconUpdated;

            if (handlers == null)
            {
                return;
            }

            // One faulty subscriber must not stop the others.
            foreach (Action<string> handler in handlers.GetInvocationList())
            {
                try
                {
                    handler(prefabName);
                }
                catch (Exception ex)
                {
                    Mod.Log.Warn($"An {nameof(IconUpdated)} handler threw: {ex}");
                }
            }
        }

        /// <summary>Opens the registry of the icons folder (no catalogue needed). Called at mod load.</summary>
        internal static void Initialize(string iconsFolder)
        {
            try
            {
                Directory.CreateDirectory(iconsFolder);
                var registry = IconRegistry.OpenShared(iconsFolder);
                string summary = registry.Load(null, null, null, 0);
                Mod.Log.Info($"{registry.Count} icon(s) available in {iconsFolder} ({summary})");
            }
            catch (Exception ex)
            {
                Mod.Log.Warn($"Icon registry not loaded: {ex.GetType().Name}: {ex.Message}");
            }
        }

        /// <summary>Maps <c>coui://buildingicons/</c> to the icons folder once the UI system exists.</summary>
        internal static void TryRegisterUriHost()
        {
            if (UriAvailable || Folder == null)
            {
                return;
            }

            try
            {
                var ui = Colossal.UI.UIManager.defaultUISystem;

                if (ui == null)
                {
                    return;
                }

                ui.AddHostLocation(UriHost, Folder, false, 0);
                UriAvailable = true;
            }
            catch (Exception ex)
            {
                Mod.Log.Warn($"UI host '{UriHost}' not registered: {ex.GetType().Name}: {ex.Message}");
            }
        }
    }
}
